```dart
/// True when [inviteHub] identifies the same hub deployment as
/// [sessionBase] (the session's REST base, e.g. `https://network.fa1.dev`).
///
/// One deployment is reachable under two names: the REST base the app
/// connects to and the `hub.`-aliased WebSocket host its agent invites
/// carry (`AddAgentDialog.hubUrl`, `wss://hub.fa1.dev/ws`). Matching is
/// origin-level — ws(s)↔http(s) scheme, host (with the `hub.` alias
/// folded), and effective port. An invite for any other deployment
/// (staging vs. production, a foreign fa_network hub) must be rejected
/// before its key is persisted.
bool isSameHubDeployment(Uri inviteHub, Uri sessionBase) {
 final sessionHost = sessionBase.host;
 final inviteHost = inviteHub.host;
 if (inviteHost != sessionHost &&
     inviteHost != 'hub.$sessionHost' &&
     sessionHost != 'hub.$inviteHost') {
   return false;
 }
 final sessionScheme = sessionBase.scheme == 'https' ? 'wss' : 'ws';
 final inviteScheme = switch (inviteHub.scheme) {
   'http' => 'ws',
   'https' => 'wss',
   final other => other,
 };
 if (inviteScheme != sessionScheme) return false;
 return _effectivePort(inviteHub, inviteScheme) ==
     _effectivePort(sessionBase, sessionScheme);
}

int _effectivePort(Uri uri, String wsScheme) =>
   uri.hasPort ? uri.port : (wsScheme == 'wss' ? 443 : 80);
```

